// NLCL game runtime for Unity: base class of every generated entity script,
// plus the NlclWorld registry.  Generated by NLCL - edit freely.
using System.Collections.Generic;
using System.Globalization;
using UnityEngine;

/// <summary>Base class of all NLCL entities (one MonoBehaviour per entity).</summary>
public abstract class NlclEntity : MonoBehaviour
{
    [Header("NLCL")]
    public string nlclId = "";          // entity identifier (snake_case)
    public string nlclKind = "object";  // entity kind (player, enemy, coin ...)
    public bool nlclControls;           // arrow keys / WASD move it (movable entity)
    public bool nlclAutoMove;           // bullets / projectiles fly by themselves
    public Vector3 nlclStart;           // initial position (used by ResetEntity)

    readonly Dictionary<int, float> _hits = new Dictionary<int, float>();
    string _appliedColor;
    Renderer _renderer;

    // ---- overridden by generated scripts --------------------------------
    public virtual object NlclGet(string field) { return null; }
    public virtual void NlclSet(string field, object value) { }
    public virtual void NlclMessage(string src, bool isDestination) { }
    public virtual void NlclRemoteInput(string src) { }
    public virtual void NlclCollision(GameObject other) { }

    protected virtual void Awake()
    {
        nlclStart = transform.position;
        _renderer = GetComponent<Renderer>();
    }

    // ---- collision: solid contacts and trigger hit-boxes, de-duplicated --
    protected virtual void OnCollisionEnter(Collision c) { Hit(c.gameObject); }
    protected virtual void OnTriggerEnter(Collider c) { Hit(c.gameObject); }

    void Hit(GameObject other)
    {
        if (other == null || other == gameObject) return;
        NlclEntity oe = other.GetComponentInParent<NlclEntity>();
        if (oe == null || oe == this) return;   // ground, scenery, own parts ...
        if (oe.transform.parent == transform || transform.parent == oe.transform) return;   // parent <-> child
        object c1 = NlclGet("collision"), c2 = oe.NlclGet("collision");
        if ((c1 is bool && !(bool)c1) || (c2 is bool && !(bool)c2)) return;   // "collision": false
        int id = other.GetInstanceID();
        float last;
        if (_hits.TryGetValue(id, out last) && Time.time - last < 0.25f) return;
        _hits[id] = Time.time;
        NlclCollision(other);
    }

    // ---- built-in movement, bullets, chasing, camera follow, visuals -----
    protected virtual void LateUpdate()
    {
        float speed = ToFloat(NlclGet("speed") ?? 5f);
        Rigidbody rb = GetComponent<Rigidbody>();
        if (nlclControls)
        {
            float h = (NlclInput.Held(KeyCode.RightArrow) || NlclInput.Held(KeyCode.D) ? 1f : 0f)
                    - (NlclInput.Held(KeyCode.LeftArrow) || NlclInput.Held(KeyCode.A) ? 1f : 0f);
            float v = (NlclInput.Held(KeyCode.UpArrow) || NlclInput.Held(KeyCode.W) ? 1f : 0f)
                    - (NlclInput.Held(KeyCode.DownArrow) || NlclInput.Held(KeyCode.S) ? 1f : 0f);
            if (rb != null && !rb.isKinematic)
            {
                Vector3 vel = GetVelocity(rb);
                vel.x = h * speed;
                if ((NlclInput.Down(KeyCode.Space) || NlclInput.Down(KeyCode.UpArrow) || NlclInput.Down(KeyCode.W))
                    && Mathf.Abs(vel.y) < 0.05f)
                    vel.y = ToFloat(NlclGet("jump_force") ?? 7f);
                SetVelocity(rb, vel);
            }
            else
            {
                transform.position += new Vector3(h, v, 0f) * speed * Time.deltaTime;
            }
        }
        if (nlclAutoMove)
        {
            Vector3 dir = Vector3.right;
            object d = NlclGet("direction");
            if (d is float[] && ((float[])d).Length >= 2)
            {
                float[] a = (float[])d;
                dir = new Vector3(a[0], a[1], a.Length > 2 ? a[2] : 0f).normalized;
            }
            transform.position += dir * speed * Time.deltaTime;
            if (transform.position.magnitude > 500f) Destroy(gameObject);  // left the world
        }
        string target = NlclGet("target") as string;
        if (!string.IsNullOrEmpty(target))
        {
            NlclEntity t = NlclWorld.Get<NlclEntity>(target);
            if (t != null)
                transform.position = Vector3.MoveTowards(transform.position, t.transform.position, speed * Time.deltaTime);
        }
        string follow = NlclGet("follow") as string;
        if (!string.IsNullOrEmpty(follow) && GetComponent<Camera>() != null)
        {
            NlclEntity f = NlclWorld.Get<NlclEntity>(follow);
            if (f != null)
                transform.position = new Vector3(f.transform.position.x, f.transform.position.y, transform.position.z);
        }
        // visuals follow the "color" / "visible" properties
        if (_renderer != null)
        {
            object vis = NlclGet("visible");
            if (vis != null) _renderer.enabled = ToBool(vis);
            string col = NlclGet("color") as string;
            if (!string.IsNullOrEmpty(col) && col != _appliedColor)
            {
                _appliedColor = col;
                Color c;
                if (ColorUtility.TryParseHtmlString(col, out c)) _renderer.material.color = c;
            }
        }
    }

    // ---- helpers used by generated code ---------------------------------
    protected void Jump()
    {
        Rigidbody rb = GetComponent<Rigidbody>();
        float force = ToFloat(NlclGet("jump_force") ?? 7f);
        if (rb != null && !rb.isKinematic)
        {
            Vector3 v = GetVelocity(rb);
            if (Mathf.Abs(v.y) < 0.05f) { v.y = force; SetVelocity(rb, v); }
        }
        else transform.position += Vector3.up;
    }

    bool _warnedSpawn;

    protected void Spawn(string template)
    {
        if (string.IsNullOrEmpty(template)) template = NlclGet("spawn") as string;
        if (string.IsNullOrEmpty(template))
        {
            if (!_warnedSpawn) Log("spawn: nothing to spawn (set the 'spawn' property)");
            _warnedSpawn = true;
            return;
        }
        NlclWorld.Spawn(template, transform.position + Vector3.right * 0.8f);
    }

    protected void ResetEntity()
    {
        transform.position = nlclStart;
        Rigidbody rb = GetComponent<Rigidbody>();
        if (rb != null && !rb.isKinematic) SetVelocity(rb, Vector3.zero);
    }

    protected void Log(string text) { Debug.Log("[" + nlclId + "] " + text); }

    protected void SetX(float v) { Vector3 p = transform.position; p.x = v; transform.position = p; }
    protected void SetY(float v) { Vector3 p = transform.position; p.y = v; transform.position = p; }
    protected void SetZ(float v) { Vector3 p = transform.position; p.z = v; transform.position = p; }

    public static Vector3 GetVelocity(Rigidbody rb)
    {
#if UNITY_6000_0_OR_NEWER
        return rb.linearVelocity;
#else
        return rb.velocity;
#endif
    }

    public static void SetVelocity(Rigidbody rb, Vector3 v)
    {
#if UNITY_6000_0_OR_NEWER
        rb.linearVelocity = v;
#else
        rb.velocity = v;
#endif
    }

    public static float ToFloat(object v)
    {
        if (v == null) return 0f;
        if (v is float) return (float)v;
        if (v is double) return (float)(double)v;
        if (v is int) return (int)v;
        if (v is long) return (long)v;
        if (v is bool) return (bool)v ? 1f : 0f;
        float f;
        return float.TryParse(v.ToString(), NumberStyles.Float, CultureInfo.InvariantCulture, out f) ? f : 0f;
    }

    public static bool ToBool(object v)
    {
        if (v == null) return false;
        if (v is bool) return (bool)v;
        if (v is string) { string s = ((string)v).ToLowerInvariant(); return s == "true" || s == "1" || s == "on" || s == "yes"; }
        return ToFloat(v) != 0f;
    }

    public static string ToStr(object v)
    {
        if (v == null) return "";
        if (v is float) return ((float)v).ToString(CultureInfo.InvariantCulture);
        if (v is double) return ((double)v).ToString(CultureInfo.InvariantCulture);
        if (v is bool) return (bool)v ? "true" : "false";
        return v.ToString();
    }
}

/// <summary>Registry of live entities (by NLCL identifier) and spawning.</summary>
public static class NlclWorld
{
    public static readonly Dictionary<string, NlclEntity> All = new Dictionary<string, NlclEntity>();
    static int _spawned;

    public static void Register(NlclEntity e)
    {
        if (e != null && !string.IsNullOrEmpty(e.nlclId)) All[e.nlclId] = e;
    }

    public static T Get<T>(string id) where T : NlclEntity
    {
        NlclEntity e;
        if (id != null && All.TryGetValue(id, out e) && e != null) return e as T;
        return null;
    }

    /// <summary>Property of another entity (null if it does not exist).</summary>
    public static object Prop(string id, string field)
    {
        NlclEntity e = Get<NlclEntity>(id);
        return e != null ? e.NlclGet(field) : null;
    }

    public static Vector3 Pos(string id)
    {
        NlclEntity e = Get<NlclEntity>(id);
        return e != null ? e.transform.position : Vector3.zero;
    }

    static readonly Dictionary<string, GameObject> _templates = new Dictionary<string, GameObject>();

    /// <summary>Keep an inactive copy of an entity so it can still be spawned after it is destroyed.
    /// hide = true turns the original itself into the (invisible) template, e.g. for bullets.</summary>
    public static void KeepTemplate(NlclEntity e, bool hide)
    {
        if (e == null) return;
        GameObject go = e.gameObject;
        if (hide) { go.SetActive(false); _templates[e.nlclId] = go; return; }
        bool was = go.activeSelf;
        go.SetActive(false);
        GameObject copy = Object.Instantiate(go);
        go.SetActive(was);
        copy.name = e.nlclId + "_template";
        _templates[e.nlclId] = copy;
    }

    public static GameObject Spawn(string template, Vector3 at)
    {
        GameObject src;
        if (template == null || !_templates.TryGetValue(template, out src) || src == null)
        {
            NlclEntity t = Get<NlclEntity>(template);
            src = t != null ? t.gameObject : null;
        }
        if (src == null) { Debug.Log("[nlcl] cannot spawn '" + template + "': it does not exist (any more)"); return null; }
        int live = 0;
        foreach (NlclEntity e in All.Values) if (e != null) live++;
        if (live >= 400) return null;   // runaway spawning guard
        GameObject go = Object.Instantiate(src, at, src.transform.rotation);
        go.SetActive(true);
        NlclEntity c = go.GetComponent<NlclEntity>();
        _spawned++;
        go.name = template + "_" + _spawned;
        if (c != null)
        {
            c.nlclId = go.name;
            c.nlclControls = false;
            c.nlclStart = at;
            Register(c);
        }
        return go;
    }

    /// <summary>All live entities (destroyed ones are skipped).</summary>
    public static List<NlclEntity> Live()
    {
        List<NlclEntity> list = new List<NlclEntity>();
        foreach (NlclEntity e in All.Values) if (e != null) list.Add(e);
        return list;
    }
}
